const ENV_IDLE = 0;
const ENV_DELAY = 1;
const ENV_ATTACK = 2;
const ENV_HOLD = 3;
const ENV_DECAY = 4;
const ENV_SUSTAIN = 5;
const ENV_RELEASE = 6;
