// ---- LUTs (built once at module load; no per-voice alloc) ----
// Absolute cents \u2192 Hz for filter Fc (SF2 range ~0..13500, pad to 14000).
const CENT_HZ_MAX = 14000;
const centToHzLut = new Float32Array(CENT_HZ_MAX + 1);
